    /**
     * 打开每个要合并的分支文件
     */
    private List<BufferedReader> openReadersForBranch(List<String> seqsList, int len, int i) {
        List<BufferedReader> readerList = new ArrayList<>();

        for (int j = 0; j < i + k; j++) {
