     */
    public AVLNode rightRotate(AVLNode parent) {
        AVLNode left = parent.left;
        AVLNode leftRight = left.right;

        // 父子交换
        left.right = parent;

        // 接收左子
        parent.left = leftRight;

        // 返回新的父节点
        return left;
