    public AVLNode balance(AVLNode unbalance) {
        if (isLL(unbalance)) {  // 左左 -> 失衡点右旋
            return rightRotate(unbalance);
        }

        if (isRR(unbalance)) { // 右右 -> 失衡点左旋
